To solve this task, we need to create a Python script that validates the specified pipeline outputs and generates a JSON summary of the validation checks. The script should be executable from the workspace root and should handle missing or empty files gracefully by reporting a failed check rather than crashing.

Here is the solution:

<solution_file path="src/validate_outputs.py">
import json
import os
import pandas as pd

def validate_file_exists(file_path):
    if not os.path.exists(file_path):
        return {
            "check_name": f"File exists: {file_path}",
            "passed": False,
            "message": f"File {file_path} does not exist."
        }
    return {
        "check_name": f"File exists: {file_path}",
        "passed": True,
        "message": f"File {file_path} exists."
    }

def validate_file_not_empty(file_path):
    if not os.path.exists(file_path):
        return {
            "check_name": f"File not empty: {file_path}",
            "passed": False,
            "message": f"File {file_path} does not exist."
        }
    if os.path.getsize(file_path) == 0:
        return {
            "check_name": f"File not empty: {file_path}",
            "passed": False,
            "message": f"File {file_path} is empty."
        }
    return {
        "check_name": f"File not empty: {file_path}",
        "passed": True,
        "message": f"File {file_path} is not empty."
    }

def validate_csv_columns(file_path, expected_columns):
    if not os.path.exists(file_path):
        return {
            "check_name": f"CSV columns: {file_path}",
            "passed": False,
            "message": f"File {file_path} does not exist."
        }
    try:
        df = pd.read_csv(file_path)
        actual_columns = set(df.columns)
        expected_columns_set = set(expected_columns)
        if actual_columns == expected_columns_set:
            return {
                "check_name": f"CSV columns: {file_path}",
                "passed": True,
                "message": f"File {file_path} has the expected columns."
            }
        else:
            return {
                "check_name": f"CSV columns: {file_path}",
                "passed": False,
                "message": f"File {file_path} does not have the expected columns. Expected: {expected_columns}, Actual: {actual_columns}"
            }
    except Exception as e:
        return {
            "check_name": f"CSV columns: {file_path}",
            "passed": False,
            "message": f"Error reading CSV file {file_path}: {str(e)}"
        }

def validate_json_keys(file_path, expected_keys):
    if not os.path.exists(file_path):
        return {
            "check_name": f"JSON keys: {file_path}",
            "passed": False,
            "message": f"File {file_path} does not exist."
        }
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
            actual_keys = set(data.keys())
            expected_keys_set = set(expected_keys)
            if actual_keys == expected_keys_set:
                return {
                    "check_name": f"JSON keys: {file_path}",
                    "passed": True,
                    "message": f"File {file_path} has the expected keys."
                }
            else:
                return {
                    "check_name": f"JSON keys: {file_path}",
                    "passed": False,
                    "message": f"File {file_path} does not have the expected keys. Expected: {expected_keys}, Actual: {actual_keys}"
                }
    except Exception as e:
        return {
            "check_name": f"JSON keys: {file_path}",
            "passed": False,
            "message": f"Error reading JSON file {file_path}: {str(e)}"
        }

def run_validations():
    validations = []

    # Validate outputs/t01_selected_indicators.csv
    validations.append(validate_file_exists("outputs/t01_selected_indicators.csv"))
    validations.append(validate_file_not_empty("outputs/t01_selected_indicators.csv"))
    validations.append(validate_csv_columns("outputs/t01_selected_indicators.csv", ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]))

    # Validate outputs/t05_clean_stops.csv
    validations.append(validate_file_exists("outputs/t05_clean_stops.csv"))
    validations.append(validate_file_not_empty("outputs/t05_clean_stops.csv"))
    validations.append(validate_csv_columns("outputs/t05_clean_stops.csv", ["stop_id", "stop_name", "stop_lat", "stop_lon"]))

    # Validate outputs/t08_pois_clean.csv
    validations.append(validate_file_exists("outputs/t08_pois_clean.csv"))
    validations.append(validate_file_not_empty("outputs/t08_pois_clean.csv"))
    validations.append(validate_csv_columns("outputs/t08_pois_clean.csv", ["qid", "label", "poi_type", "latitude", "longitude", "source"]))

    # Validate outputs/t10_accessibility_scores.csv
    validations.append(validate_file_exists("outputs/t10_accessibility_scores.csv"))
    validations.append(validate_file_not_empty("outputs/t10_accessibility_scores.csv"))
    validations.append(validate_csv_columns("outputs/t10_accessibility_scores.csv", ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]))

    # Validate outputs/t13_city_clusters.csv
    validations.append(validate_file_exists("outputs/t13_city_clusters.csv"))
    validations.append(validate_file_not_empty("outputs/t13_city_clusters.csv"))

    # Write the validation summary to outputs/t14_validation_summary.json
    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(validations, f, indent=2)

if __name__ == "__main__":
    run_validations()
